import{_ as a,o,c as t,a2 as n}from"./chunks/framework.D21_4UK8.js";const g=JSON.parse('{"title":"🎙️ Guía Maestra de Micrófonos, Tomas e Ingeniería de Audio","description":"","frontmatter":{},"headers":[],"relativePath":"es/guia-microfonos-tomas.md","filePath":"es/guia-microfonos-tomas.md"}'),s={name:"es/guia-microfonos-tomas.md"};function r(i,e,l,d,c,u){return o(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="🎙️-guia-maestra-de-microfonos-tomas-e-ingenieria-de-audio" tabindex="-1">🎙️ Guía Maestra de Micrófonos, Tomas e Ingeniería de Audio <a class="header-anchor" href="#🎙️-guia-maestra-de-microfonos-tomas-e-ingenieria-de-audio" aria-label="Permalink to &quot;🎙️ Guía Maestra de Micrófonos, Tomas e Ingeniería de Audio&quot;">​</a></h1><h3 id="acustica-del-cono-evm-12l-fisica-de-la-fase-mezcla-dual-y-el-secreto-del-estereo-en-una-sola-pista" tabindex="-1">Acústica del Cono EVM-12L, Física de la Fase, Mezcla Dual y el Secreto del Estéreo en Una Sola Pista <a class="header-anchor" href="#acustica-del-cono-evm-12l-fisica-de-la-fase-mezcla-dual-y-el-secreto-del-estereo-en-una-sola-pista" aria-label="Permalink to &quot;Acústica del Cono EVM-12L, Física de la Fase, Mezcla Dual y el Secreto del Estéreo en Una Sola Pista&quot;">​</a></h3><p><strong>TattooYou Vintage Amplifier &amp; Studio Suite | Main St Audio Labs</strong></p><hr><h2 id="📖-prologo-el-arte-de-capturar-un-amplificador-legendario" tabindex="-1">📖 Prólogo: El Arte de Capturar un Amplificador Legendario <a class="header-anchor" href="#📖-prologo-el-arte-de-capturar-un-amplificador-legendario" aria-label="Permalink to &quot;📖 Prólogo: El Arte de Capturar un Amplificador Legendario&quot;">​</a></h2><p>En las grabaciones legendarias de finales de los años 70 y principios de los 80, el sonido de la guitarra eléctrica dejó de ser un simple micrófono puesto al descuido frente a un amplificador. Los grandes ingenieros de estudio descubrieron que la interacción entre el <strong>mueble de madera dura</strong>, la <strong>fidelidad sin saturación del altavoz</strong> y la <strong>combinación milimétrica de micrófonos en fase</strong> era el verdadero secreto detrás de ese tono gigante, tridimensional y con presencia que salta de los parlantes.</p><p>El módulo <strong>1x12 Hardwood Cab Lab</strong> integrado en <strong>TattooYou</strong> recrea con precisión científica todo ese entorno de estudio. Este documento detalla la física acústica detrás del gabinete, la respuesta en frecuencia del cono, el comportamiento de la fase y cómo utilizar el motor de <strong>convolución dual</strong> para lograr mezclas de nivel profesional.</p><hr><h2 id="🔊-1-la-fisica-del-altavoz-evm-12l-y-el-gabinete-hardwood" tabindex="-1">🔊 1. La Física del Altavoz EVM-12L y el Gabinete Hardwood <a class="header-anchor" href="#🔊-1-la-fisica-del-altavoz-evm-12l-y-el-gabinete-hardwood" aria-label="Permalink to &quot;🔊 1. La Física del Altavoz EVM-12L y el Gabinete Hardwood&quot;">​</a></h2><h3 id="a-cero-distorsion-del-cono-zero-speaker-breakup" tabindex="-1">A. Cero Distorsión del Cono (<em>Zero Speaker Breakup</em>) <a class="header-anchor" href="#a-cero-distorsion-del-cono-zero-speaker-breakup" aria-label="Permalink to &quot;A. Cero Distorsión del Cono (*Zero Speaker Breakup*)&quot;">​</a></h3><p>La mayoría de los altavoces de guitarra tradicionales (como los conos británicos clásicos de 25W o 30W) tienen una respuesta no lineal: cuando el amplificador empuja potencia, la membrana de papel flexiona y satura, añadiendo un grano áspero en medios-agudos y comprimiendo los graves.</p><p>El <strong>EVM-12L</strong> (200W–300W continuos, imán cerámico masivo de 7.5 kg y chasis de fundición de aluminio) fue diseñado con un objetivo opuesto:</p><ul><li><strong>Fidelidad y Headroom Masivo:</strong> El cono no deforma la señal ni añade distorsión armónica propia. Toda la compresión, saturación y textura armónica que escuchas proviene <strong>puramente de las válvulas 6L6 y del circuito del previo Mark I (&#39;78)</strong>.</li><li><strong>Separación Quirúrgica de Cuerdas:</strong> Los acordes complejos y las afinaciones abiertas (como el Sol abierto de Keith Richards) mantienen cada cuerda individual perfectamente distinguible, sin empastarse.</li></ul><h3 id="b-mueble-de-madera-dura-con-sintonia-bass-reflex" tabindex="-1">B. Mueble de Madera Dura con Sintonía Bass-Reflex <a class="header-anchor" href="#b-mueble-de-madera-dura-con-sintonia-bass-reflex" aria-label="Permalink to &quot;B. Mueble de Madera Dura con Sintonía Bass-Reflex&quot;">​</a></h3><p>A diferencia de los gabinetes estándar de aglomerado con fondo abierto (<em>open back</em>), esta caja construida en <strong>madera dura maciza (<em>hardwood</em>)</strong> cuenta con un puerto de ventilación inferior:</p><ul><li><strong>Graves Secos y Controlados:</strong> La resonancia acústica del puerto refuerza las frecuencias entre <strong>80 Hz y 160 Hz</strong> con un amortiguamiento crítico, eliminando el retumbe descontrolado o la &quot;bola de graves&quot; al tocar rítmicas pesadas o afinaciones bajas.</li></ul><hr><h2 id="🎯-2-la-acustica-del-cono-mapa-de-posicionamiento" tabindex="-1">🎯 2. La Acústica del Cono: Mapa de Posicionamiento <a class="header-anchor" href="#🎯-2-la-acustica-del-cono-mapa-de-posicionamiento" aria-label="Permalink to &quot;🎯 2. La Acústica del Cono: Mapa de Posicionamiento&quot;">​</a></h2><p>La superficie de un altavoz de 12 pulgadas no irradia el sonido de manera homogénea. A medida que alejamos la cápsula del micrófono del centro hacia el borde, la masa acústica del cono atenúa las frecuencias ultra-altas y realza el cuerpo:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  ┌──────────────────────────────────────────────┐</span></span>
<span class="line"><span>                  │                 CONO DEL ALTAVOZ             │</span></span>
<span class="line"><span>                  │                                              │</span></span>
<span class="line"><span>                  │      ( -3 )      ( -2 )      ( -1 )   ( 0 )  │</span></span>
<span class="line"><span>                  │      Borde        Cono      Borde Cap  Centro │</span></span>
<span class="line"><span>                  │     (Oscuro)    (Cálido)    (Balance) (Brillo)│</span></span>
<span class="line"><span>                  │                                              │</span></span>
<span class="line"><span>                  │  [ PORT ]  &lt;─── (Ranura bass-reflex de aire) │</span></span>
<span class="line"><span>                  └──────────────────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:center;">Toma</th><th style="text-align:left;">Posición Física</th><th style="text-align:left;">Respuesta en Frecuencia</th><th style="text-align:left;">Carácter Tonal y Caso de Uso Ideal</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>0: Direct</code></strong></td><td style="text-align:left;"><strong>Centro / Dust Cap</strong></td><td style="text-align:left;">Realce en <strong>4 kHz – 8 kHz</strong>.</td><td style="text-align:left;">Máximo ataque de púa, súper brillante y cortante. Ideal para solos que deben atravesar mezclas densas o funk percusivo.</td></tr><tr><td style="text-align:center;"><strong><code>+1: Edge</code></strong></td><td style="text-align:left;"><strong>Borde del Cap</strong></td><td style="text-align:left;">Ataque claro con agudos levemente suavizados.</td><td style="text-align:left;">El tono clásico de rock rítmico con mordida definida y presencia enérgica.</td></tr><tr><td style="text-align:center;"><strong><code>-1: Sweet</code></strong></td><td style="text-align:left;"><strong>Transición Cap-Cono</strong></td><td style="text-align:left;">Curva equilibrada (<strong>Punto Dulce</strong>).</td><td style="text-align:left;"><strong>El estándar de estudio:</strong> Balance óptimo de graves, medios crujientes y agudos sedosos. Excelente punto de partida para cualquier estilo.</td></tr><tr><td style="text-align:center;"><strong><code>-2: Warm</code></strong></td><td style="text-align:left;"><strong>Cuerpo del Cono</strong></td><td style="text-align:left;">Medios redondos, caída suave sobre 5 kHz.</td><td style="text-align:left;">Sonido cálido y fuera de eje. Ideal para domar pastillas de puente muy brillantes (Telecaster, Stratocaster).</td></tr><tr><td style="text-align:center;"><strong><code>-3: Dark</code></strong></td><td style="text-align:left;"><strong>Borde Exterior</strong></td><td style="text-align:left;">Graves profundos, agudos totalmente atenuados.</td><td style="text-align:left;">Tono grueso y oscuro. Perfecto para Jazz aterciopelado, Blues vintage o guitarras con afinaciones agresivas.</td></tr><tr><td style="text-align:center;"><strong><code>Port: Bass</code></strong></td><td style="text-align:left;"><strong>Ranura Bass-Reflex</strong></td><td style="text-align:left;">Pico de energía en <strong>80 Hz – 160 Hz</strong>.</td><td style="text-align:left;">Captura el empuje de aire del puerto inferior. Añade la pegada en el pecho y el peso característico de una caja 4x12.</td></tr><tr><td style="text-align:center;"><strong><code>Room 3D</code></strong></td><td style="text-align:left;"><strong>Sala de Grabación</strong></td><td style="text-align:left;">Acústica tridimensional y reflexiones naturales.</td><td style="text-align:left;">Par estéreo a distancia en la sala del estudio. Elimina la sensación artificial de &quot;caja seca&quot; y sitúa el ampli en un espacio real.</td></tr></tbody></table><hr><h2 id="🎧-3-el-secreto-fisico-de-las-tomas-left-l-y-right-r" tabindex="-1">🎧 3. El Secreto Físico de las Tomas Left (L) y Right (R) <a class="header-anchor" href="#🎧-3-el-secreto-fisico-de-las-tomas-left-l-y-right-r" aria-label="Permalink to &quot;🎧 3. El Secreto Físico de las Tomas Left (L) y Right (R)&quot;">​</a></h2><p>Todas las posiciones cuentan con tomas <strong><code>L</code> (Izquierda)</strong> y <strong><code>R</code> (Derecha)</strong> (ejemplo: <code>57 L -1</code> y <code>57 R -1</code>):</p><h3 id="¿por-que-suenan-sutilmente-distintas-si-el-parlante-es-redondo" tabindex="-1">¿Por qué suenan sutilmente distintas si el parlante es redondo? <a class="header-anchor" href="#¿por-que-suenan-sutilmente-distintas-si-el-parlante-es-redondo" aria-label="Permalink to &quot;¿Por qué suenan sutilmente distintas si el parlante es redondo?&quot;">​</a></h3><ol><li><strong>Asimetría Física de la Bobina:</strong> Los cables flexibles que conectan los terminales con la bobina móvil (<em>tinsel leads</em>) van soldados sobre uno de los hemisferios del cono. Esa microscópica diferencia de masa y rigidez altera la respuesta armónica entre el lado izquierdo y derecho.</li><li><strong>Veta y Estructura del Mueble:</strong> La madera natural y el flujo de aire del puerto interior generan micro-reflexiones asimétricas que un micrófono de estudio de alta gama registra con total fidelidad.</li></ol><hr><h2 id="🔬-4-la-ciencia-de-la-fase-cero-cancelacion-destructiva" tabindex="-1">🔬 4. La Ciencia de la Fase: Cero Cancelación Destructiva <a class="header-anchor" href="#🔬-4-la-ciencia-de-la-fase-cero-cancelacion-destructiva" aria-label="Permalink to &quot;🔬 4. La Ciencia de la Fase: Cero Cancelación Destructiva&quot;">​</a></h2><h3 id="a-el-peligro-del-filtro-peine-comb-filtering" tabindex="-1">A. El Peligro del Filtro Peine (<em>Comb Filtering</em>) <a class="header-anchor" href="#a-el-peligro-del-filtro-peine-comb-filtering" aria-label="Permalink to &quot;A. El Peligro del Filtro Peine (*Comb Filtering*)&quot;">​</a></h3><p>En un estudio físico real, si colocas dos micrófonos frente al cono con una mínima diferencia de distancia de apenas 1 o 2 milímetros:</p><ul><li>La onda llega a un micrófono unos microsegundos antes que al otro.</li><li>Las frecuencias cuya longitud de onda coincide con ese retardo chocan a $180^\\circ$ de polaridad opuesta y <strong>se anulan mutuamente</strong>.</li><li><strong>El resultado sonoro:</strong> La guitarra pierde toda su pegada en graves y suena &quot;flaca, nasal y hueca&quot;.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                ONDA MIC A:    ──/\\──\\/──/\\──\\/──</span></span>
<span class="line"><span>                ONDA MIC B:    ──\\/──/\\──\\/──/\\──  (Desfasada 180°)</span></span>
<span class="line"><span>                               ──────────────────</span></span>
<span class="line"><span>                SUMA RESULTANTE: ────────────────  (¡Cancelación / Sonido a lata!)</span></span></code></pre></div><h3 id="b-como-resuelve-la-fase-tattooyou-alineacion-por-transiente-sample-accurate" tabindex="-1">B. Cómo Resuelve la Fase TattooYou: Alineación por Transiente (<em>Sample-Accurate</em>) <a class="header-anchor" href="#b-como-resuelve-la-fase-tattooyou-alineacion-por-transiente-sample-accurate" aria-label="Permalink to &quot;B. Cómo Resuelve la Fase TattooYou: Alineación por Transiente (*Sample-Accurate*)&quot;">​</a></h3><p>En el desarrollo de <strong>TattooYou</strong>, todas las tomas del gabinete fueron calibradas mediante <strong>Transformada de Fase Mínima (<em>Minimum Phase Transform</em>)</strong>:</p><ol><li>El ataque transitorio inicial de cada micrófono y posición comienza exactamente en la <strong>muestra cero ($t = 0$)</strong>.</li><li><strong>Correlación Positiva Superior a $+0.92$:</strong> En todo el rango de graves y medios fundamentales (80 Hz a 3 kHz), la correlación es prácticamente $+1.0$. <strong>Los graves nunca se cancelan; se suman y se refuerzan con mayor solidez</strong>.</li><li><strong>Micro-textura en Agudos (&gt; 4 kHz):</strong> Las micro-diferencias en el extremo agudo actúan como un suavizado analógico natural (<em>phase smoothing</em>), eliminando asperezas sin destruir la señal.</li></ol><hr><h2 id="🎛️-5-perfiles-de-microfonos" tabindex="-1">🎛️ 5. Perfiles de Micrófonos <a class="header-anchor" href="#🎛️-5-perfiles-de-microfonos" aria-label="Permalink to &quot;🎛️ 5. Perfiles de Micrófonos&quot;">​</a></h2><h3 id="_1-shure-57-dinamico-cardioide" tabindex="-1">1. Shure 57 (Dinámico Cardioide) <a class="header-anchor" href="#_1-shure-57-dinamico-cardioide" aria-label="Permalink to &quot;1. Shure 57 (Dinámico Cardioide)&quot;">​</a></h3><ul><li><strong>Carácter:</strong> El estándar indiscutido de la historia del rock.</li><li><strong>Respuesta:</strong> Realce característico en los 3 kHz – 6 kHz que empuja la guitarra hacia el frente de la mezcla con ataque de púa y mordisco definido.</li></ul><h3 id="_2-neumann-87-condensador-de-gran-diafragma" tabindex="-1">2. Neumann 87 (Condensador de Gran Diafragma) <a class="header-anchor" href="#_2-neumann-87-condensador-de-gran-diafragma" aria-label="Permalink to &quot;2. Neumann 87 (Condensador de Gran Diafragma)&quot;">​</a></h3><ul><li><strong>Carácter:</strong> Fidelidad de estudio de gama alta (<em>Hi-Fi</em>).</li><li><strong>Respuesta:</strong> Curva de frecuencia ancha y lineal, con graves profundos, cuerpo aterciopelado y agudos ultra detallados con &quot;aire&quot; de estudio.</li></ul><h3 id="_3-u87-room-l-room-r-par-estereo-de-sala" tabindex="-1">3. U87 Room L / Room R (Par Estéreo de Sala) <a class="header-anchor" href="#_3-u87-room-l-room-r-par-estereo-de-sala" aria-label="Permalink to &quot;3. U87 Room L / Room R (Par Estéreo de Sala)&quot;">​</a></h3><ul><li><strong>Carácter:</strong> Captura la acústica tridimensional de la sala de grabación.</li><li><strong>Uso:</strong> Perfecto para monitoreo con auriculares o para aportar profundidad espacial real sin necesidad de añadir reverbs artificiales.</li></ul><hr><h2 id="🎛️-6-arquitectura-dsp-motor-de-convolucion-dual-en-paralelo" tabindex="-1">🎛️ 6. Arquitectura DSP: Motor de Convolución Dual en Paralelo <a class="header-anchor" href="#🎛️-6-arquitectura-dsp-motor-de-convolucion-dual-en-paralelo" aria-label="Permalink to &quot;🎛️ 6. Arquitectura DSP: Motor de Convolución Dual en Paralelo&quot;">​</a></h2><p>En lugar de limitarte a un solo archivo IR fijo, <strong>TattooYou</strong> integra la consola <strong>1x12 Hardwood Cab Lab</strong> con dos motores de convolución (<code>cab1Convolution</code> y <code>cab2Convolution</code>) corriendo en paralelo a latencia cero:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                                  SEÑAL DEL PREVIO Y ETAPA 6L6</span></span>
<span class="line"><span>                                                │</span></span>
<span class="line"><span>                       ┌────────────────────────┴────────────────────────┐</span></span>
<span class="line"><span>                       ▼                                                 ▼</span></span>
<span class="line"><span>             [ CONVOLUCIÓN MIC 1 ]                             [ CONVOLUCIÓN MIC 2 ]</span></span>
<span class="line"><span>             Toma: 57 L (-1) Sweet                             Toma: 87 L (0) Direct (o 57 R)</span></span>
<span class="line"><span>             Fader: -24 dB a +6 dB                             Fader: -24 dB a +6 dB</span></span>
<span class="line"><span>             Nivel ponderado: w1                               Fase: Normal / Invertida (Ø)</span></span>
<span class="line"><span>                       │                                       Nivel ponderado: w2</span></span>
<span class="line"><span>                       │                                                 │</span></span>
<span class="line"><span>                       └────────────────────────┬────────────────────────┘</span></span>
<span class="line"><span>                                                ▼</span></span>
<span class="line"><span>                                    SECCIÓN MASTER DEL CAB LAB</span></span>
<span class="line"><span>                                  (Perilla BLEND: Equal-Power)</span></span>
<span class="line"><span>                                                │</span></span>
<span class="line"><span>                        ┌───────────────────────┴───────────────────────┐</span></span>
<span class="line"><span>                        ▼                                               ▼</span></span>
<span class="line"><span>               MODO MONO (MONO SUM)                           MODO STEREO SPREAD 3D</span></span>
<span class="line"><span>          Suma ponderada al centro:                      Canal Izquierdo = Mic 1 * (w1 * √2)</span></span>
<span class="line"><span>          Out = (Mic1 * w1) + (Mic2 * w2)                Canal Derecho   = Mic 2 * (w2 * √2)</span></span></code></pre></div><hr><h2 id="⚖️-7-mono-vs-stereo-spread-¿como-aplicar-el-blend-segun-tu-necesidad" tabindex="-1">⚖️ 7. MONO vs. STEREO SPREAD: ¿Cómo Aplicar el Blend según tu Necesidad? <a class="header-anchor" href="#⚖️-7-mono-vs-stereo-spread-¿como-aplicar-el-blend-segun-tu-necesidad" aria-label="Permalink to &quot;⚖️ 7. MONO vs. STEREO SPREAD: ¿Cómo Aplicar el Blend según tu Necesidad?&quot;">​</a></h2><p>El verdadero poder de TattooYou radica en cómo combinas los dos micrófonos mediante los dos modos de salida disponibles:</p><hr><h3 id="a-modo-mono-mono-sum-switch-stereo-spread-apagado" tabindex="-1">A. Modo MONO (<code>Mono Sum</code> - Switch Stereo Spread Apagado) <a class="header-anchor" href="#a-modo-mono-mono-sum-switch-stereo-spread-apagado" aria-label="Permalink to &quot;A. Modo MONO (\`Mono Sum\` - Switch Stereo Spread Apagado)&quot;">​</a></h3><p>En este modo, ambos micrófonos procesan la señal y <strong>se suman directamente en fase al centro de la pista</strong>.</p><h4 id="¿cuando-usar-modo-mono" tabindex="-1">¿Cuándo usar Modo Mono? <a class="header-anchor" href="#¿cuando-usar-modo-mono" aria-label="Permalink to &quot;¿Cuándo usar Modo Mono?&quot;">​</a></h4><ul><li>Guitarras rítmicas principales dentro de una mezcla densa de banda completa (batería pesada, bajo, teclados y voces).</li><li>Pistas de guitarra mono tradicionales donde buscas un <strong>tono ultra compacto, gordo y con pegada central</strong>.</li></ul><h4 id="¿como-aplicar-el-blend-en-mono" tabindex="-1">¿Cómo aplicar el <code>BLEND</code> en Mono? <a class="header-anchor" href="#¿como-aplicar-el-blend-en-mono" aria-label="Permalink to &quot;¿Cómo aplicar el \`BLEND\` en Mono?&quot;">​</a></h4><ol><li><p><strong>El Truco del Promedio de Cono (Sumar Toma L + Toma R del MISMO Micrófono):</strong></p><ul><li><strong>Mic 1:</strong> <code>57 L (-1) Sweet</code></li><li><strong>Mic 2:</strong> <code>57 R (-1) Sweet</code></li><li><strong>Blend al 50% en Mono:</strong><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Toma 57 &quot;L&quot; ──┐</span></span>
<span class="line"><span>              ├───&gt; SUMA EN MONO ───&gt; SUAVIZADO NATURAL DE AGUDOS (PHASE SMOOTHING)</span></span>
<span class="line"><span>Toma 57 &quot;R&quot; ──┘</span></span></code></pre></div></li><li><strong>Qué ocurre acústicamente:</strong> Como los picos resonantes de los agudos ocurren en frecuencias ligeramente distintas en el lado izquierdo y derecho del cono, al sumarse en mono se promedian. Se eliminan las asperezas o &quot;chispazos&quot; estridentes y los medios ganan un cuerpo y densidad analógica impresionante sin necesidad de usar ecualizadores.</li></ul></li><li><p><strong>Combinación Dinámico + Condensador (Ataque + Cuerpo Hi-Fi):</strong></p><ul><li><strong>70% Mic 1 (57 Sweet) + 30% Mic 2 (87 Direct):</strong> El 57 aporta la presencia y el crujido para cortar la mezcla, mientras que el 87 rellena los graves y el aire superior.</li></ul></li><li><p><strong>Inyección de Sub-Graves (Ataque + BassPort):</strong></p><ul><li><strong>75% Mic 1 (57 Sweet) + 25% Mic 2 (57 BassPort):</strong> Mantienes la definición en el ataque de púa mientras inyectas el empuje y peso en el pecho de una caja 4x12.</li></ul></li></ol><hr><h3 id="b-modo-stereo-stereo-spread-3d-switch-stereo-spread-encendido" tabindex="-1">B. Modo STEREO (<code>STEREO SPREAD 3D</code> - Switch Stereo Spread Encendido) <a class="header-anchor" href="#b-modo-stereo-stereo-spread-3d-switch-stereo-spread-encendido" aria-label="Permalink to &quot;B. Modo STEREO (\`STEREO SPREAD 3D\` - Switch Stereo Spread Encendido)&quot;">​</a></h3><p>En este modo, el <strong>Micrófono 1 se envía al canal izquierdo (L)</strong> y el <strong>Micrófono 2 al canal derecho (R)</strong> con una compensación automática de ganancia de <strong>+3 dB ($\\sqrt{2}$)</strong> para mantener la energía intacta.</p><h4 id="🚀-el-gran-beneficio-estereo-gigante-en-una-sola-pista-sin-duplicar-pistas" tabindex="-1">🚀 El Gran Beneficio: Estéreo Gigante en UNA SOLA PISTA (<em>Sin Duplicar Pistas</em>) <a class="header-anchor" href="#🚀-el-gran-beneficio-estereo-gigante-en-una-sola-pista-sin-duplicar-pistas" aria-label="Permalink to &quot;🚀 El Gran Beneficio: Estéreo Gigante en UNA SOLA PISTA (*Sin Duplicar Pistas*)&quot;">​</a></h4><ul><li><strong>Te ahorras clonar pistas en el DAW:</strong> No necesitas crear dos canales, desfasar eventos ni lidiar con plugins de ensanchamiento artificial que arruinan la compatibilidad mono.</li><li><strong>Espacialidad analógica real:</strong> Al alimentar cada oído con una perspectiva acústica ligeramente distinta del mismo cono (o con dos micrófonos complementarios), tu cerebro percibe inmediatamente el <strong>tamaño físico real del amplificador en la habitación</strong>.</li></ul><h4 id="¿como-aplicar-el-blend-en-modo-stereo" tabindex="-1">¿Cómo aplicar el <code>BLEND</code> en Modo Stereo? <a class="header-anchor" href="#¿como-aplicar-el-blend-en-modo-stereo" aria-label="Permalink to &quot;¿Cómo aplicar el \`BLEND\` en Modo Stereo?&quot;">​</a></h4><ol><li><strong>La Técnica de Doble Tracking Ancho (<em>Wide Double Track</em>):</strong><ul><li><strong>Mic 1:</strong> <code>57 L (-1) Sweet</code> (100% al oído izquierdo).</li><li><strong>Mic 2:</strong> <code>57 R (-1) Sweet</code> (100% al oído derecho).</li><li><strong>Blend en 50%:</strong> Logras una separación estéreo inmensa, limpia y ultra-natural para guitarras rítmicas abiertas con una sola pista en el proyecto.</li></ul></li><li><strong>La Técnica de Directo en Estudio (<em>Studio Live 3D</em>):</strong><ul><li><strong>Mic 1:</strong> <code>57 L (-1) Sweet</code> (Sonido directo pegado al frente a la izquierda).</li><li><strong>Mic 2:</strong> <code>87 Room L 3D</code> (Ambiente y reflexiones de la sala a la derecha).</li><li><strong>Blend en 25%–30%:</strong> Tienes la guitarra perfectamente ubicada con un halo tridimensional de sala que se abre naturalmente en el espacio estéreo.</li></ul></li><li><strong>Monitoreo con Auriculares sin Fatiga:</strong><ul><li>Tocar o practicar con auriculares en modo Stereo Spread elimina la fatiga auditiva que causan los simuladores tradicionales que suenan &quot;en el centro exacto del cráneo&quot;.</li></ul></li></ol><hr><h3 id="📊-cuadro-comparativo-¿mono-o-stereo-spread" tabindex="-1">📊 Cuadro Comparativo: ¿Mono o Stereo Spread? <a class="header-anchor" href="#📊-cuadro-comparativo-¿mono-o-stereo-spread" aria-label="Permalink to &quot;📊 Cuadro Comparativo: ¿Mono o Stereo Spread?&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Necesidad de Producción</th><th style="text-align:center;">Modo Recomendado</th><th style="text-align:left;">Configuración de Micrófonos</th><th style="text-align:center;">Ajuste de Blend Sugerido</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Guitarras Rítmicas en Mezcla Completa</strong></td><td style="text-align:center;"><strong>MONO</strong></td><td style="text-align:left;">Mic 1: <code>57 L Sweet</code> + Mic 2: <code>87 L Direct</code></td><td style="text-align:center;"><strong>30% a 40%</strong></td></tr><tr><td style="text-align:left;"><strong>Suavizar Agudos Estridentes / Tono Gordo</strong></td><td style="text-align:center;"><strong>MONO</strong></td><td style="text-align:left;">Mic 1: <code>57 L Sweet</code> + Mic 2: <code>57 R Sweet</code></td><td style="text-align:center;"><strong>50% (Suma L + R)</strong></td></tr><tr><td style="text-align:left;"><strong>Riffs Pesados / Afinaciones Bajas</strong></td><td style="text-align:center;"><strong>MONO</strong></td><td style="text-align:left;">Mic 1: <code>57 L Sweet</code> + Mic 2: <code>57 L BassPort</code></td><td style="text-align:center;"><strong>20% a 30%</strong></td></tr><tr><td style="text-align:left;"><strong>Rítmica Estéreo en 1 Sola Pista</strong></td><td style="text-align:center;"><strong>STEREO</strong></td><td style="text-align:left;">Mic 1: <code>57 L Sweet</code> + Mic 2: <code>57 R Sweet</code></td><td style="text-align:center;"><strong>50% (Balance Central)</strong></td></tr><tr><td style="text-align:left;"><strong>Intros, Arpegios Limpios y Solos Espaciales</strong></td><td style="text-align:center;"><strong>STEREO</strong></td><td style="text-align:left;">Mic 1: <code>57 L Sweet</code> + Mic 2: <code>87 Room L 3D</code></td><td style="text-align:center;"><strong>25% a 35%</strong></td></tr><tr><td style="text-align:left;"><strong>Tono Solista Clásico Directo</strong></td><td style="text-align:center;"><strong>MONO</strong></td><td style="text-align:left;">Mic 1: <code>57 L Sweet</code> + Mic 2: <em>Off</em></td><td style="text-align:center;"><strong>0% (100% Mic 1)</strong></td></tr><tr><td style="text-align:left;"><strong>Guitarras Acústicas / Hi-Fi Transparentes</strong></td><td style="text-align:center;"><strong>MONO / STEREO</strong></td><td style="text-align:left;">Mic 1: <code>87 L Direct</code> + Mic 2: <code>87 R Open</code></td><td style="text-align:center;"><strong>50%</strong></td></tr></tbody></table><hr><h2 id="🏆-8-presets-de-estudio-integrados" tabindex="-1">🏆 8. Presets de Estudio Integrados <a class="header-anchor" href="#🏆-8-presets-de-estudio-integrados" aria-label="Permalink to &quot;🏆 8. Presets de Estudio Integrados&quot;">​</a></h2><p>En el menú superior de la consola <strong>Cab Lab</strong> puedes cargar con un solo clic las 6 combinaciones maestras:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 1. 🎸 Studio Standard  ──&gt; 57 L Sweet + 87 L Direct  (Blend 30%, Mono)</span></span>
<span class="line"><span> 2. 🥊 Heavy Punch      ──&gt; 57 L Sweet + 57 L BassPort (Blend 25%, Mono)</span></span>
<span class="line"><span> 3. 🌌 Live Room 3D     ──&gt; 57 L Sweet + 87 Room L 3D  (Blend 25%, Stereo)</span></span>
<span class="line"><span> 4. 🎧 Wide Double Track──&gt; 57 L Sweet + 57 R Sweet   (Blend 50%, Stereo)</span></span>
<span class="line"><span> 5. ⚡ Solo 57 Classic  ──&gt; 57 L Sweet (Mic 2 Apagado, Mono)</span></span>
<span class="line"><span> 6. ✨ Solo 87 Hi-Fi    ──&gt; 87 L Direct (Mic 2 Apagado, Mono)</span></span></code></pre></div><hr><h2 id="💡-9-flujo-de-trabajo-rapido-en-tu-daw" tabindex="-1">💡 9. Flujo de Trabajo Rápido en tu DAW <a class="header-anchor" href="#💡-9-flujo-de-trabajo-rapido-en-tu-daw" aria-label="Permalink to &quot;💡 9. Flujo de Trabajo Rápido en tu DAW&quot;">​</a></h2><ol><li><strong>Ajuste en Tiempo Real desde la Carátula:</strong><ul><li>En la esquina superior derecha del frontal del amplificador tienes la <strong>mini-perilla BLEND</strong>.</li><li>Puedes ajustar la proporción de la mezcla de micrófonos en cualquier momento mientras reproduces la canción en tu DAW sin abrir la ventana flotante.</li></ul></li><li><strong>Acceso a la Consola Completa:</strong><ul><li>Haz clic sobre el botón <strong><code>CAB LAB</code></strong> o directamente sobre el nombre del micrófono en la pantalla superior para abrir la consola detallada, ajustar los faders individuales de ganancia (-24 dB a +6 dB) o alternar entre Mono y Stereo Spread.</li></ul></li><li><strong>Compatibilidad Mono Garantizada:</strong><ul><li>Gracias a la alineación a muestra cero ($t=0$), incluso si utilizas el modo Stereo Spread, cuando tu mezcla se reproduzca en un altavoz monofónico (como la radio de un coche o el altavoz de un teléfono móvil), la señal <strong>no sufrirá cancelaciones de fase destructivas</strong>, manteniendo todo el volumen y la pegada del amplificador.</li></ul></li></ol>`,74)])])}const m=a(s,[["render",r]]);export{g as __pageData,m as default};
